import { corsHeaders } from '../_shared/cors.ts';
import { authenticateRequest } from '../_shared/auth.ts';
// Evidence is generated by domain-table triggers, never by client-supplied claims.
Deno.serve(async (req) => {
 if (req.method === 'OPTIONS') return new Response(null, { headers: corsHeaders });
 const auth = await authenticateRequest(req);
 if (auth instanceof Response) return auth;
 return new Response(JSON.stringify({ error: 'Record events through the authorised attendance, assessment, lab or placement workflow.' }), {
  status: 403, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
 });
});
